def parse_markdown(text: str) -> str:
    '''BUGGY: Unsafe link handling (no scheme validation, no href escaping).'''
    import re
    from html import escape as _escape

    if text is None:
        raise TypeError('text must be a str')
    if not isinstance(text, str):
        raise TypeError('text must be a str')

    text = text.replace('\r\n', '\n').replace('\r', '\n')

    heading_re = re.compile(r'^(#{1,6}) (.*)$')
    bold_re = re.compile(r'\*\*([^\n]+?)\*\*')
    code_re = re.compile(r'`([^`\n]*)`')
    link_re = re.compile(r'\[([^\]\n]+)\]\(([^)\s]+)\)')

    def _inline(s: str) -> str:
        # Escape visible text, but BUG: href uses raw URL.
        def repl_code(m):
            return '<code>' + _escape(m.group(1), quote=True) + '</code>'

        def repl_bold(m):
            return '<strong>' + _escape(m.group(1), quote=True) + '</strong>'

        def repl_link(m):
            label = _escape(m.group(1), quote=True)
            url = m.group(2)  # BUG: raw, not escaped, not validated.
            return '<a href="' + url + '">' + label + '</a>'

        s = code_re.sub(repl_code, s)
        s = bold_re.sub(repl_bold, s)
        s = link_re.sub(repl_link, s)
        return _escape(s, quote=True).replace('&lt;code&gt;', '<code>').replace('&lt;/code&gt;', '</code>').replace('&lt;strong&gt;', '<strong>').replace('&lt;/strong&gt;', '</strong>').replace('&lt;a ', '<a ').replace('&lt;/a&gt;', '</a>').replace('&gt;', '>')

    blocks = []
    para = []
    in_code = False
    code_lines = []

    def flush_para():
        nonlocal para
        if para:
            blocks.append('<p>' + '<br>'.join(_inline(x) for x in para) + '</p>')
            para = []

    def flush_code():
        nonlocal code_lines
        blocks.append('<pre><code>' + _escape('\n'.join(code_lines), quote=True) + '</code></pre>')
        code_lines = []

    for line in text.split('\n'):
        if line.strip() == '~~~':
            if in_code:
                flush_code()
                in_code = False
            else:
                flush_para()
                in_code = True
            continue

        if in_code:
            code_lines.append(line)
            continue

        m = heading_re.match(line)
        if m:
            flush_para()
            level = len(m.group(1))
            blocks.append('<h' + str(level) + '>' + _inline(m.group(2)) + '</h' + str(level) + '>')
            continue

        if line.strip() == '':
            flush_para()
            continue

        para.append(line)

    if in_code:
        flush_code()
    else:
        flush_para()

    return ''.join(blocks)
